package publish

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"
)

var (
	ErrSensitiveContent = errors.New("item contains sensitive content")
	ErrUntrustedModel   = errors.New("item from untrusted model")
	ErrUnverifiedItem   = errors.New("item is unverified")
)

type Provenance struct {
	ExtractorModel  string `json:"extractor_model,omitempty"`
	ReconcilerModel string `json:"reconciler_model,omitempty"`
}

type Review struct {
	State string `json:"state,omitempty"`
	By    string `json:"by,omitempty"`
	At    string `json:"at,omitempty"`
}

type Item struct {
	ID         string            `json:"id"`
	Title      string            `json:"title"`
	Body       string            `json:"body"`
	Status     string            `json:"status"`
	VerifiedAt string            `json:"verified_at,omitempty"`
	Provenance *Provenance       `json:"provenance,omitempty"`
	Review     *Review           `json:"review,omitempty"`
	Metadata   map[string]string `json:"metadata,omitempty"`
}

type Indexer interface {
	IndexItem(ctx context.Context, item *Item) error
}

type LocalPublisher struct {
	dataDir string
	repoID  string
	indexer Indexer
}

func NewLocalPublisher(dataDir, repoID string, indexer Indexer) *LocalPublisher {
	return &LocalPublisher{
		dataDir: dataDir,
		repoID:  repoID,
		indexer: indexer,
	}
}

func (p *LocalPublisher) Publish(ctx context.Context, item *Item) error {
	// Security gating: check for sensitive content
	if isSensitive(item.Title) || isSensitive(item.Body) {
		return ErrSensitiveContent
	}

	// Security gating: block unverified items
	if item.Status != "verified" && item.Status != "merged" && item.Status != "confirmed" {
		if item.VerifiedAt == "" {
			return ErrUnverifiedItem
		}
	}

	// External provenance gating
	if item.Provenance != nil {
		if strings.Contains(strings.ToLower(item.Provenance.ExtractorModel), "untrusted") ||
			strings.Contains(strings.ToLower(item.Provenance.ReconcilerModel), "untrusted") {
			return ErrUntrustedModel
		}
	}

	// Mark as unreviewed
	if item.Review == nil {
		item.Review = &Review{}
	}
	item.Review.State = "unreviewed"
	item.Review.By = "system"
	item.Review.At = time.Now().Format(time.RFC3339)

	// Ensure pending directory exists
	pendingDir := filepath.Join(p.dataDir, p.repoID, "pending")
	if err := os.MkdirAll(pendingDir, 0755); err != nil {
		return fmt.Errorf("creating pending directory: %w", err)
	}

	// Write item
	filePath := filepath.Join(pendingDir, item.ID+".md")
	content := fmt.Sprintf("# %s\n\n%s\n", item.Title, item.Body)
	if err := os.WriteFile(filePath, []byte(content), 0644); err != nil {
		return fmt.Errorf("writing item: %w", err)
	}

	// Immediate indexing
	if p.indexer != nil {
		if err := p.indexer.IndexItem(ctx, item); err != nil {
			return fmt.Errorf("indexing item: %w", err)
		}
	}

	return nil
}

func isSensitive(text string) bool {
	lower := strings.ToLower(text)
	sensitiveWords := []string{"password", "secret", "token", "api_key", "private_key"}
	for _, word := range sensitiveWords {
		if strings.Contains(lower, word) {
			return true
		}
	}
	return false
}

package publish

import (
	"context"
	"os"
	"path/filepath"
	"testing"
)

type mockIndexer struct {
	indexed []*Item
}

func (m *mockIndexer) IndexItem(ctx context.Context, item *Item) error {
	m.indexed = append(m.indexed, item)
	return nil
}

func TestLocalPublisher_Publish(t *testing.T) {
	tempDir, err := os.MkdirTemp("", "local-publisher-test")
	if err != nil {
		t.Fatal(err)
	}
	defer os.RemoveAll(tempDir)

	idx := &mockIndexer{}
	pub := NewLocalPublisher(tempDir, "repo-123", idx)

	t.Run("success", func(t *testing.T) {
		item := &Item{
			ID:         "item-1",
			Title:      "Normal Item",
			Body:       "This is a normal item",
			Status:     "verified",
			VerifiedAt: "commit-123",
		}

		err := pub.Publish(context.Background(), item)
		if err != nil {
			t.Fatalf("expected nil, got %v", err)
		}

		// check file
		pendingDir := filepath.Join(tempDir, "repo-123", "pending")
		filePath := filepath.Join(pendingDir, "item-1.md")
		if _, err := os.Stat(filePath); os.IsNotExist(err) {
			t.Fatalf("expected file to exist at %s", filePath)
		}

		// check review status
		if item.Review == nil || item.Review.State != "unreviewed" {
			t.Errorf("expected review state unreviewed, got %v", item.Review)
		}

		// check index
		if len(idx.indexed) != 1 {
			t.Errorf("expected 1 indexed item, got %d", len(idx.indexed))
		}
	})

	t.Run("sensitive", func(t *testing.T) {
		item := &Item{
			ID:    "item-2",
			Title: "I have a password here",
			Body:  "secret",
		}
		err := pub.Publish(context.Background(), item)
		if err != ErrSensitiveContent {
			t.Fatalf("expected ErrSensitiveContent, got %v", err)
		}
	})

	t.Run("unverified", func(t *testing.T) {
		item := &Item{
			ID:     "item-3",
			Title:  "Unverified item",
			Status: "observed",
		}
		err := pub.Publish(context.Background(), item)
		if err != ErrUnverifiedItem {
			t.Fatalf("expected ErrUnverifiedItem, got %v", err)
		}
	})

	t.Run("untrusted model", func(t *testing.T) {
		item := &Item{
			ID:         "item-4",
			Title:      "Untrusted item",
			Status:     "verified",
			VerifiedAt: "commit-123",
			Provenance: &Provenance{
				ExtractorModel: "untrusted-v1",
			},
		}
		err := pub.Publish(context.Background(), item)
		if err != ErrUntrustedModel {
			t.Fatalf("expected ErrUntrustedModel, got %v", err)
		}
	})
}

package tick

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"sync"
	"time"

	"github.com/cblabs-org/repo-memory-plugin/internal/core/config"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/episode"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/evidence"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/index"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/jobs"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/pipeline/publish"
	"github.com/cblabs-org/repo-memory-plugin/internal/core/spool"
	"github.com/cblabs-org/repo-memory-plugin/internal/harness"
)

type PipelineExecutor struct {
	hk          harness.Housekeeper
	dataDir     string
	repoRoot    string
	repoID      string
	store       *jobs.Store
	epStore     *episode.Store
	idx         *index.Index
	cfg         config.RepoConfig
	budgetLimit int
	budgetUsed  int
	mu          sync.Mutex
}

func (t *Ticker) ProcessPipeline(ctx context.Context, store *jobs.Store, repoRoot, repoID string) error {
	if t.hk == nil {
		return nil
	}

	cfg, err := config.LoadRepoConfig(repoRoot)
	if err != nil {
		return fmt.Errorf("loading repo config: %w", err)
	}

	repoDataDir := filepath.Join(t.dataDir, repoID)
	epStore := episode.NewStore(t.dataDir, repoID)
	idx, err := index.NewIndex(filepath.Join(repoDataDir, "index.sqlite"))
	if err != nil {
		return fmt.Errorf("opening index: %w", err)
	}
	defer idx.Close()

	exec := &PipelineExecutor{
		hk:          t.hk,
		dataDir:     t.dataDir,
		repoRoot:    repoRoot,
		repoID:      repoID,
		store:       store,
		epStore:     epStore,
		idx:         idx,
		cfg:         cfg,
		budgetLimit: cfg.Budgets.DailyTokens,
	}

	return exec.Run(ctx)
}

func (p *PipelineExecutor) checkBudget(cost *jobs.Cost) error {
	p.mu.Lock()
	defer p.mu.Unlock()
	if cost != nil {
		p.budgetUsed += cost.InputTokens + cost.OutputTokens
	}
	if p.budgetLimit > 0 && p.budgetUsed >= p.budgetLimit {
		return fmt.Errorf("daily token budget exceeded")
	}
	return nil
}

// NewPipelineExecutor creates a PipelineExecutor for pipeline processing.
func NewPipelineExecutor(dataDir, repoRoot, repoID string, store *jobs.Store, epStore *episode.Store) *PipelineExecutor {
	return &PipelineExecutor{
		dataDir:  dataDir,
		repoRoot: repoRoot,
		repoID:   repoID,
		store:    store,
		epStore:  epStore,
	}
}

// SetHousekeeper sets the housekeeper harness for the executor.
func (p *PipelineExecutor) SetHousekeeper(hk harness.Housekeeper) {
	p.hk = hk
}

type usageTracker struct {
	hk    harness.Housekeeper
	mu    sync.Mutex
	usage harness.Usage
}

func newUsageTracker(hk harness.Housekeeper) *usageTracker {
	return &usageTracker{hk: hk}
}

func (u *usageTracker) Run(ctx context.Context, stage harness.Stage, input any) (harness.Result, error) {
	if u.hk == nil {
		return harness.Result{}, fmt.Errorf("no housekeeper configured")
	}
	res, err := u.hk.Run(ctx, stage, input)
	u.mu.Lock()
	u.usage.InputTokens += res.Usage.InputTokens
	u.usage.OutputTokens += res.Usage.OutputTokens
	u.usage.ThinkingTokens += res.Usage.ThinkingTokens
	u.usage.CacheReadTokens += res.Usage.CacheReadTokens
	u.mu.Unlock()
	return res, err
}

func (u *usageTracker) Cost() jobs.Cost {
	u.mu.Lock()
	defer u.mu.Unlock()
	return jobs.FromUsage(u.usage)
}

// ConvertCapturesToEvidence exposes convertCapturesToEvidence for testing and direct invocation.
func (p *PipelineExecutor) ConvertCapturesToEvidence(ctx context.Context) error {
	return p.convertCapturesToEvidence(ctx)
}

func (p *PipelineExecutor) Run(ctx context.Context) error {
	if err := p.convertCapturesToEvidence(ctx); err != nil {
		return err
	}

	log.Println("v1 pipeline stages removed; v2 distillation not yet implemented")

	return nil
}

func (p *PipelineExecutor) convertCapturesToEvidence(ctx context.Context) error {
	if p.epStore == nil {
		p.epStore = episode.NewStore(p.dataDir, p.repoID)
	}

	for {
		job, err := p.store.AcquireNext(ctx, 5*time.Minute, jobs.KindCapture)
		if err != nil {
			if errors.Is(err, jobs.ErrNoJobAvailable) {
				break
			}
			return err
		}

		var entry spool.Entry
		if err := json.Unmarshal([]byte(job.Payload), &entry); err != nil || entry.ConversationID == "" {
			_ = p.store.Complete(ctx, job.ID, nil)
			continue
		}

		transcriptPath := entry.TranscriptPath
		queueCandidate := filepath.Join(p.dataDir, p.repoID, "queue", entry.ConversationID+".jsonl")
		if _, err := os.Stat(queueCandidate); err == nil {
			transcriptPath = queueCandidate
		} else if transcriptPath != "" {
			if _, err := os.Stat(transcriptPath); err != nil {
				transcriptPath = ""
			}
		}

		if transcriptPath == "" {
			p.store.Fail(ctx, job.ID, fmt.Sprintf("no transcript path for conversation %s", entry.ConversationID), 5*time.Minute)
			continue
		}

		parsed, err := evidence.ParseTranscript(transcriptPath)
		if err != nil {
			p.store.Fail(ctx, job.ID, fmt.Sprintf("failed to parse transcript %s: %v", transcriptPath, err), 5*time.Minute)
			continue
		}

		entry.TranscriptPath = transcriptPath
		ep := evidence.BuildEpisode(entry, parsed, p.repoID)

		if _, err := p.epStore.WriteEpisode(ep); err != nil {
			p.store.Fail(ctx, job.ID, fmt.Sprintf("failed to write episode for %s: %v", entry.ConversationID, err), 5*time.Minute)
			continue
		}

		_ = p.store.Complete(ctx, job.ID, nil)
	}
	return nil
}

func (p *PipelineExecutor) processPublish(ctx context.Context) error {
	for {
		if err := p.checkBudget(nil); err != nil {
			return err
		}

		job, err := p.store.AcquireNext(ctx, 5*time.Minute, jobs.KindPublish)
		if err != nil {
			if errors.Is(err, jobs.ErrNoJobAvailable) {
				break
			}
			return err
		}

		publisher := publish.NewLocalPublisher(p.dataDir, p.repoID, nil)
		item := &publish.Item{
			ID:         job.Payload,
			Title:      job.Payload,
			Body:       job.Payload,
			Status:     "verified",
			VerifiedAt: time.Now().Format(time.RFC3339),
		}
		if err := publisher.Publish(ctx, item); err != nil {
			if errors.Is(err, harness.ErrQuotaExhausted) {
				p.store.Fail(ctx, job.ID, err.Error(), 5*time.Minute)
				return err
			}
			p.store.Fail(ctx, job.ID, err.Error(), 5*time.Minute)
			continue
		}

		_ = p.store.Complete(ctx, job.ID, &jobs.Cost{})
	}
	return nil
}

